// App-only downloads: keep generated bytes in this card, never write an
// arbitrary host path or send an artifact through model-visible content.
export function createWorkspaceDownloads() {
  const urls = new Set();
  const types = { gif: 'image/gif', png: 'image/png', svg: 'image/svg+xml', pdf: 'application/pdf', tiff: 'image/tiff' };
  return {
    save({ name = 'molecule', format = 'gif', dataBase64, gifBase64 }) {
      const encoded = dataBase64 ?? gifBase64;
      if (!Object.hasOwn(types, format) || typeof encoded !== 'string' || encoded.length > Math.ceil(16 * 1024 * 1024 / 3) * 4
        || !/^[A-Za-z0-9+/]*={0,2}$/u.test(encoded)) throw new Error('Invalid export format or artifact exceeds 16 MiB.');
      const bytes = Uint8Array.from(atob(encoded), character => character.charCodeAt(0));
      const text = new TextDecoder().decode(bytes.subarray(0, 2048));
      const valid = format === 'gif' ? /^GIF8[79]a/u.test(text) && bytes.at(-1) === 59
        : format === 'png' ? bytes.subarray(0, 8).join(',') === '137,80,78,71,13,10,26,10'
        : format === 'pdf' ? text.startsWith('%PDF-')
        : format === 'tiff' ? ['73,73,42,0', '77,77,0,42'].includes(bytes.subarray(0, 4).join(','))
        : /<svg[\s>]/u.test(text);
      if (!valid || bytes.length < 14 || bytes.length > 16 * 1024 * 1024) throw new Error('Invalid export artifact.');
      if (urls.size >= 20) throw new Error('This card already contains 20 downloads. Open a new workspace to export more.');
      name = String(name).replace(/[^a-zA-Z0-9._-]/gu, '_').slice(0, 100).replace(/\.(gif|svg|png|pdf|tiff)$/iu, '') + '.' + format;
      const downloadUrl = URL.createObjectURL(new Blob([bytes], { type: types[format] }));
      urls.add(downloadUrl);
      // No on-disk path is claimed: the browser/host controls final delivery.
      return { name, path: '', downloadUrl };
    },
    dispose() { for (const url of urls) URL.revokeObjectURL(url); urls.clear(); },
  };
}
